# -*- coding: utf-8 -*-
"""ENG/KER13 v24 -- the TTA2 + SECTTA2 z-flip view sets, carried by the aux dataset.

The blocks are VERBATIM the ones ENG/KER14's landed objects produced (each proved to
rebuild its own landed detector sha), and the anchors are the ones its handoff names.
Each block is a no-op unless its own env key is set, so the text is identical whether the
stack is armed or not -- which is why one _osk_expect covers both.
"""
SCHEMA = "ker13-stack-1.0"

TTA2_ANCHOR = '            for f in range(W):\n                det_logits[f] = det_logits[f] / _nv\n'

TTA2_BLOCK = '            if os.environ.get("BIOHUB_TTA_ZFLIP", "0").strip() != "0":\n                _imz = imgs.flip((-3,))\n                _, _dz = model.encode(_imz)\n                for f in range(W):\n                    det_logits[f] = det_logits[f] + _dz[f].flip((-3,))\n                del _dz\n                _nv += 1\n                for dims in [(-1,), (-2,), (-2, -1)]:\n                    _imzf = _imz.flip(dims)\n                    _, _dzf = model.encode(_imzf)\n                    for f in range(W):\n                        det_logits[f] = det_logits[f] + _dzf[f].flip(dims).flip((-3,))\n                    del _imzf, _dzf\n                    _nv += 1\n                for _k in (1, 3):\n                    _imzr = torch.rot90(_imz, _k, dims=(-2, -1))\n                    _, _dzr = model.encode(_imzr)\n                    for f in range(W):\n                        det_logits[f] = det_logits[f] + torch.rot90(\n                            _dzr[f], -_k, dims=(-2, -1)).flip((-3,))\n                    del _imzr, _dzr\n                    _nv += 1\n                _imzt = _imz.transpose(-1, -2)\n                _, _dzt = model.encode(_imzt)\n                for f in range(W):\n                    det_logits[f] = det_logits[f] + _dzt[f].transpose(-1, -2).flip((-3,))\n                del _imzt, _dzt\n                _nv += 1\n                _imzat = torch.rot90(_imz, 1, dims=(-2, -1)).transpose(-1, -2)\n                _, _dzat = model.encode(_imzat)\n                for f in range(W):\n                    det_logits[f] = det_logits[f] + torch.rot90(\n                        _dzat[f].transpose(-1, -2), -1, dims=(-2, -1)).flip((-3,))\n                del _imzat, _dzat\n                _nv += 1\n                del _imz\n                print("TTA2 z-flip armed : %d views" % _nv, flush=True)\n'

SECTTA2_ANCHOR = '                    for f in range(W):\n                        secondary_det_logits[f] = secondary_det_logits[f] / _secondary_nv\n'

SECTTA2_BLOCK = '                    if os.environ.get("BIOHUB_SECTTA_ZFLIP", "0").strip() != "0":\n                        _simz = imgs.flip((-3,))\n                        _, _sdz = secondary_model.encode(_simz)\n                        for f in range(W):\n                            secondary_det_logits[f] = (\n                                secondary_det_logits[f] + _sdz[f].flip((-3,)))\n                        del _sdz\n                        _secondary_nv += 1\n                        for dims in [(-1,), (-2,), (-2, -1)]:\n                            _simzf = _simz.flip(dims)\n                            _, _sdzf = secondary_model.encode(_simzf)\n                            for f in range(W):\n                                secondary_det_logits[f] = (\n                                    secondary_det_logits[f]\n                                    + _sdzf[f].flip(dims).flip((-3,)))\n                            del _simzf, _sdzf\n                            _secondary_nv += 1\n                        for _k in (1, 3):\n                            _simzr = torch.rot90(_simz, _k, dims=(-2, -1))\n                            _, _sdzr = secondary_model.encode(_simzr)\n                            for f in range(W):\n                                secondary_det_logits[f] = (\n                                    secondary_det_logits[f] + torch.rot90(\n                                        _sdzr[f], -_k, dims=(-2, -1)).flip((-3,)))\n                            del _simzr, _sdzr\n                            _secondary_nv += 1\n                        _simzt = _simz.transpose(-1, -2)\n                        _, _sdzt = secondary_model.encode(_simzt)\n                        for f in range(W):\n                            secondary_det_logits[f] = (\n                                secondary_det_logits[f]\n                                + _sdzt[f].transpose(-1, -2).flip((-3,)))\n                        del _simzt, _sdzt\n                        _secondary_nv += 1\n                        _simzat = torch.rot90(_simz, 1, dims=(-2, -1)).transpose(-1, -2)\n                        _, _sdzat = secondary_model.encode(_simzat)\n                        for f in range(W):\n                            secondary_det_logits[f] = (\n                                secondary_det_logits[f] + torch.rot90(\n                                    _sdzat[f].transpose(-1, -2), -1,\n                                    dims=(-2, -1)).flip((-3,)))\n                        del _simzat, _sdzat\n                        _secondary_nv += 1\n                        del _simz\n                        print("SECTTA2 z-flip armed : %d views" % _secondary_nv, flush=True)\n'
